CREATE FUNCTION c1_api.public_stores(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ BEGIN
 PERFORM c1_private.cursor_guard(n,q);
 RETURN jsonb_build_object('items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.store,'closed',s.closed,'paused',s.paused,'controlRevision',s.control_revision,'financial',s.totals) ORDER BY s.store COLLATE "C"),'[]') FROM (SELECT s.*,r.totals FROM c1_private.stores s JOIN c1_private.rollups r USING(ns,store) WHERE s.ns=n AND s.store COLLATE "C">coalesce(q->>'after','') COLLATE "C" ORDER BY s.store COLLATE "C" LIMIT coalesce((q->>'limit')::int,20)) s),'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.public_meals(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ BEGIN
 PERFORM c1_private.cursor_guard(n,q);
 RETURN jsonb_build_object('items',(SELECT coalesce(jsonb_agg(c1_private.term_dto(n,h.store,h.meal,h.version)||jsonb_build_object('listed',h.listed) ORDER BY h.meal COLLATE "C"),'[]') FROM (SELECT * FROM c1_private.catalog_head WHERE ns=n AND store=q->>'store' AND meal COLLATE "C">coalesce(q->>'after','') COLLATE "C" ORDER BY meal COLLATE "C" LIMIT coalesce((q->>'limit')::int,20)) h),'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.public_meal(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE h c1_private.catalog_head;BEGIN SELECT * INTO h FROM c1_private.catalog_head WHERE ns=n AND store=q->>'store' AND meal=q->>'meal';IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;RETURN c1_private.term_dto(n,h.store,h.meal,h.version)||jsonb_build_object('listed',h.listed,'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.public_image(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE b bytea;BEGIN SELECT t.image INTO b FROM c1_private.terms t JOIN c1_private.catalog_head h USING(ns,store,meal) WHERE t.ns=n AND t.image_digest=c1_private.h(q->>'digest') AND c1_private.content_available(n,t.store,t.meal,t.version) AND t.version<=h.version LIMIT 1;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;RETURN jsonb_build_object('image',encode(b,'base64'));END $$;
CREATE FUNCTION c1_api.draft_get(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;dr c1_private.drafts;BEGIN s=c1_private.auth(n,q);PERFORM c1_private.owner_auth(n,s,q->>'store','catalog');SELECT * INTO dr FROM c1_private.drafts WHERE ns=n AND store=q->>'store' AND meal=q->>'meal';IF NOT FOUND THEN RETURN jsonb_build_object('revision',0,'name','','description','','price','1','windows','[[0,1440]]'::jsonb);END IF;RETURN jsonb_build_object('revision',dr.revision,'name',convert_from(dr.name,'UTF8'),'description',convert_from(dr.description,'UTF8'),'price',dr.price::text,'windows',dr.windows,'imageDigest',encode(dr.image_digest,'hex'),'hasImage',dr.image IS NOT NULL);END $$;
CREATE FUNCTION c1_api.draft_save(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;dr c1_private.drafts;rev bigint;BEGIN PERFORM c1_private.guard(n,true);s=c1_private.auth(n,q,true);PERFORM c1_private.owner_auth(n,s,q->>'store','catalog');PERFORM c1_private.windows(q->'windows');PERFORM c1_private.money(q->'price');IF octet_length(convert_to(q->>'name','UTF8')) NOT BETWEEN 1 AND 200 OR octet_length(convert_to(q->>'description','UTF8'))>8192 OR position(chr(13) IN q->>'name')>0 OR position(chr(13) IN q->>'description')>0 THEN PERFORM c1_private.fail('INVALID_BODY');END IF;SELECT * INTO dr FROM c1_private.drafts WHERE ns=n AND store=q->>'store' AND meal=q->>'meal' FOR UPDATE;rev=coalesce(dr.revision,0);IF rev<>(q->>'expectedRevision')::bigint THEN PERFORM c1_private.fail('CONFLICT');END IF;INSERT INTO c1_private.drafts(ns,store,meal,revision,name,description,price,windows) VALUES(n,q->>'store',q->>'meal',rev+1,convert_to(q->>'name','UTF8'),convert_to(q->>'description','UTF8'),c1_private.money(q->'price'),q->'windows') ON CONFLICT(ns,store,meal) DO UPDATE SET revision=rev+1,name=EXCLUDED.name,description=EXCLUDED.description,price=EXCLUDED.price,windows=EXCLUDED.windows;RETURN jsonb_build_object('revision',rev+1);END $$;
CREATE FUNCTION c1_api.draft_image(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;BEGIN PERFORM c1_private.guard(n,true);s=c1_private.auth(n,q,true);PERFORM c1_private.owner_auth(n,s,q->>'store','catalog');UPDATE c1_private.drafts SET image=decode(q->>'image','base64'),image_digest=c1_private.h(q->>'image_digest'),revision=revision+1 WHERE ns=n AND store=q->>'store' AND meal=q->>'meal' AND revision=(q->>'expectedRevision')::bigint;IF NOT FOUND THEN PERFORM c1_private.fail('CONFLICT');END IF;RETURN jsonb_build_object('revision',(q->>'expectedRevision')::bigint+1);END $$;
CREATE FUNCTION c1_api.draft_review(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;dr c1_private.drafts;h c1_private.catalog_head;st c1_private.stores;payload jsonb;BEGIN d=c1_private.guard(n,true);s=c1_private.auth(n,q,true);PERFORM c1_private.owner_auth(n,s,q->>'store','catalog');SELECT * INTO dr FROM c1_private.drafts WHERE ns=n AND store=q->>'store' AND meal=q->>'meal';IF NOT FOUND OR dr.image IS NULL OR dr.revision<>(q->>'expectedRevision')::bigint THEN PERFORM c1_private.fail('CONFLICT');END IF;SELECT * INTO h FROM c1_private.catalog_head WHERE ns=n AND store=dr.store AND meal=dr.meal;SELECT * INTO st FROM c1_private.stores WHERE ns=n AND store=dr.store;payload=jsonb_build_object('store',dr.store,'meal',dr.meal,'version',coalesce(h.version,0)+1,'draftRevision',dr.revision,'currentVersion',coalesce(h.version,0),'controlRevision',st.control_revision,'name',convert_from(dr.name,'UTF8'),'description',convert_from(dr.description,'UTF8'),'price',dr.price::text,'windows',dr.windows,'imageDigest',encode(dr.image_digest,'hex'),'image',encode(dr.image,'base64'));INSERT INTO c1_private.reviews VALUES(n,(q->>'review_id')::uuid,s.subject,'publish',payload,d.now+300);RETURN jsonb_build_object('reviewId',q->>'review_id','expiresAt',d.now+300,'terms',payload-'image');END $$;
CREATE FUNCTION c1_api.draft_publish(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;r c1_private.reviews;dr c1_private.drafts;st c1_private.stores;h c1_private.catalog_head;p jsonb;old jsonb;gr bigint;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);gr=c1_private.owner_auth(n,s,q->>'store','catalog');old=c1_private.idem(n,s,'publish',q);IF old IS NOT NULL THEN RETURN old;END IF;PERFORM c1_private.guard(n,true);SELECT * INTO r FROM c1_private.reviews WHERE ns=n AND id=(q->'client'->>'reviewId')::uuid AND subject=s.subject AND kind='publish';IF NOT FOUND OR r.expires<=d.now THEN PERFORM c1_private.fail('STALE_REVIEW');END IF;p=r.payload;SELECT * INTO dr FROM c1_private.drafts WHERE ns=n AND store=p->>'store' AND meal=p->>'meal';SELECT * INTO st FROM c1_private.stores WHERE ns=n AND store=dr.store;SELECT * INTO h FROM c1_private.catalog_head WHERE ns=n AND store=dr.store AND meal=dr.meal;IF dr.revision<>(p->>'draftRevision')::bigint OR coalesce(h.version,0)<>(p->>'currentVersion')::bigint OR st.control_revision<>(p->>'controlRevision')::bigint THEN PERFORM c1_private.fail('CONFLICT');END IF;
 IF EXISTS(SELECT 1 FROM c1_private.terms WHERE ns=n AND store=dr.store AND meal=dr.meal AND version=(p->>'version')::bigint) THEN PERFORM c1_private.fail('CONFLICT');END IF;
 INSERT INTO c1_private.terms VALUES(n,dr.store,dr.meal,(p->>'version')::bigint,decode(q->>'body','base64'),dr.image,c1_private.h(q->>'body_digest'),dr.image_digest,c1_private.h(q->>'terms_hash'),dr.price,dr.windows,dr.name,dr.description,true);
 p=(p-'image')||jsonb_build_object('deadline',d.now+300,'body_digest','0x'||(q->>'body_digest'),'image_digest','0x'||encode(dr.image_digest,'hex'),'terms_hash','0x'||(q->>'terms_hash'),'price',dr.price::text);RETURN c1_private.new_intent(n,s,'publish',q,p,false,gr);END $$;
CREATE FUNCTION c1_api.control_confirm(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;st c1_private.stores;old jsonb;a text=q->>'action';p jsonb;gr bigint;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);gr=c1_private.owner_auth(n,s,q->>'store','catalog');IF a NOT IN('list','pause','close') THEN PERFORM c1_private.fail('INVALID_ACTION');END IF;old=c1_private.idem(n,s,a,q);IF old IS NOT NULL THEN RETURN old;END IF;PERFORM c1_private.guard(n,true);SELECT * INTO st FROM c1_private.stores WHERE ns=n AND store=q->>'store';IF st.control_revision<>(q->'client'->>'expectedRevision')::bigint OR (a='list' AND st.closed) OR (a='close' AND st.closed) THEN PERFORM c1_private.fail('CONFLICT');END IF;p=q->'client'||jsonb_build_object('store',st.store,'deadline',d.now+300,'controlRevision',st.control_revision);RETURN c1_private.new_intent(n,s,a,q,p,false,gr);END $$;
